
import json
from pathlib import Path
from .models import AddonConfig
from .generator import generate
from .logging import get_logger
from .supervisor import get

def bootstrap(validate_only=False):
    log=get_logger()
    data={}
    p=Path('/data/options.json')
    if p.exists():
        data=json.loads(p.read_text())
    cfg=AddonConfig.model_validate(data)
    if cfg.auto_mqtt:
        svc=get('services/mqtt')
        if svc:
            try:
                d=svc["data"]
                cfg.mqtt.host=d.get("host",cfg.mqtt.host)
                cfg.mqtt.port=d.get("port",cfg.mqtt.port)
            except Exception:
                pass
    if validate_only:
        log.info("Configuration validated")
        return 0
    generate(cfg)
    log.info("Configuration generated")
    return 0
